const paths={building:'M6 22V3h12v19M3 22h18M9 6h1m4 0h1M9 10h1m4 0h1M9 14h1m4 0h1M10 22v-4h4v4',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6',wallet:'M20 7V4H5a3 3 0 0 0 0 6h15v10H5a3 3 0 0 1-3-3V7m13 6h6v4h-6z',percent:'M19 5 5 19M7 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6M17 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6',bank:'m3 9 9-6 9 6H3zm0 12h18M6 12v6m6-6v6m6-6v6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 0-8 0 4 4 0 0 0 8 0',transfer:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',chart:'M3 3v18h18M7 14v3m5-9v9m5-13v13',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 3 2 2-1 3 3 2 2-1 3 2 3-2 2 1 3-2-1-3 2-2-2-3-3-1-1-3z',search:'M21 21l-5-5M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',moon:'M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16',menu:'M3 6h18M3 12h18M3 18h18',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',trash:'M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',more:'M5 12h.01M12 12h.01M19 12h.01',shield:'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10',logout:'M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9',key:'M15 7a2 2 0 1 0 0 .01M21 2l-9.6 9.6M15.5 7.5l3 3L22 7l-3-3M7.5 14a5.5 5.5 0 1 0 0 11 5.5 5.5 0 0 0 0-11',edit:'M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0)+' ₺';
const fmtDate=d=>d?d.split('-').reverse().join('.'):'—';
const sum=(rows,fn)=>rows.reduce((s,x)=>s+fn(x),0);
let db=APP.db,ME=APP.me,state={stab:'banka',bank:0,bstart:'',bend:'',bdir:'all',kind:'all',dir:'all',wtab:'alis',page:'Genel Bakış',project:'0',period:'all',search:'',status:'Tümü',report:0,cari:'',start:'',end:'',hidden:[],tab:'Tümü',detailTab:'Hareketler'},lastFocus=null;
const can=k=>!!ME.perms?.[k],canEdit=k=>ME.perms?.[k]==='edit';
const projName=id=>db.projects.find(p=>p.id===Number(id))?.name||'—';
const initials=n=>String(n||'?').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toLocaleUpperCase('tr');
const ym=d=>d.toLocaleDateString('sv-SE',{timeZone:'Europe/Istanbul'}).slice(0,7);
/* Grafik: bugünden geriye son 6 ay */
function lastMonths(n=6){const t=new Date(today()+'T12:00:00');return Array.from({length:n},(_,j)=>{const d=new Date(t.getFullYear(),t.getMonth()-(n-1-j),15);return {prefix:ym(d),label:d.toLocaleDateString('tr-TR',{month:'short'}).replace('.','')}})}
/* Dönem seçimi: kayıtlardaki aylar */
function periodOptions(){const set=new Set([...db.invoices.map(i=>i.date.slice(0,7)),ym(new Date())]);return [['all','Tüm dönemler'],...[...set].sort().reverse().map(m=>[m,new Date(m+'-15T12:00:00').toLocaleDateString('tr-TR',{month:'long',year:'numeric'})])]}
function pageLink(key,html){const p=PAGES.find(x=>x[3]===key);return p?html.replace('{url}',p[0]):''}
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Istanbul'});
const party=id=>db.parties.find(p=>p.id===id)?.name||'—';
const net=i=>Math.round(i.base*(1+i.vat/100-i.vat/100*i.rate-(i.stopaj||0)/100)*100)/100;
let _pdb=null,_pidx=null;const payIndex=()=>{if(_pdb!==db){_pdb=db;_pidx=new Map();for(const p of db.payments){if(p.void)continue;if(!_pidx.has(p.invoice))_pidx.set(p.invoice,[]);_pidx.get(p.invoice).push(p)}}return _pidx};
const paid=i=>sum(payIndex().get(i.id)||[],p=>p.amount);

/* İade faturası: asıl faturanın kalanından düşer; ödenmiş faturada fazlası karşı taraftan geri alınır / müşteriye ödenir. */
const isRet=i=>!!i?.ret;
const sg=i=>isRet(i)?-1:1;
const flowIn=i=>isRet(i)?!isIncome(i):isIncome(i);
const snet=i=>sg(i)*net(i);
const sbase=i=>sg(i)*i.base;
let _rdb=null,_ridx=null;const retIndex=()=>{if(_rdb!==db){_rdb=db;_ridx=new Map();for(const r of db.invoices){if(!r.ret)continue;if(!_ridx.has(r.ret))_ridx.set(r.ret,[]);_ridx.get(r.ret).push(r)}}return _ridx};
const retsOf=i=>retIndex().get(i.id)||[];
const credit=i=>sum(retsOf(i),net);
function refundable(r){const o=db.invoices.find(x=>x.id===r.ret);if(!o)return 0;let over=Math.max(0,paid(o)+credit(o)-net(o));for(const x of [...retsOf(o)].sort((a,b)=>b.pk-a.pk)){const part=Math.min(net(x),over);over=Math.max(0,over-part);if(x.pk===r.pk)return Math.max(0,Math.round((part-paid(x))*100)/100)}return 0}
const remain=i=>isRet(i)?refundable(i):Math.max(0,Math.round((net(i)-paid(i)-credit(i))*100)/100);
const returnableBase=i=>Math.round((i.base-sum(retsOf(i),r=>r.base))*100)/100;
const billStatus=i=>isRet(i)?(remain(i)<.01?'Mahsup edildi':'İade bekleniyor'):remain(i)<.01?'Ödendi':(paid(i)>0||credit(i)>0)?'Kısmi ödendi':'Ödenmedi';
const addDays=(d,n)=>{const x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return x.toLocaleDateString('sv-SE')};
const daysTo=d=>Math.round((Date.parse(d+'T12:00:00')-Date.parse(today()+'T12:00:00'))/86400000);
/* Muhasebe yardımcıları: KDV, tevkifat, stopaj, gelir/gider */
const kdv=i=>sg(i)*Math.round(i.base*i.vat)/100;
const wAmt=i=>sg(i)*Math.round(i.base*i.vat*i.rate)/100;
const stopajAmt=i=>sg(i)*Math.round(i.base*(i.stopaj||0))/100;
const isIncome=i=>i?.dir==='gelir';
const invOf=p=>db.invoices.find(i=>i.id===p.invoice);
const partyLabel=i=>i?.party?party(i.party):(i?.cp||'—');
const statusLabel=i=>isRet(i)?(remain(i)<.01?'İade mahsup edildi':flowIn(i)?'İade tahsil edilecek':'İade ödenecek'):isIncome(i)?{'Ödendi':'Tahsil edildi','Kısmi ödendi':'Kısmi tahsil','Ödenmedi':'Tahsil edilmedi'}[billStatus(i)]:billStatus(i);
const tags=i=>[isRet(i)?(isIncome(i)?'Satış iadesi':'Alış iadesi'):isIncome(i)?'Gelir':'Gider',i.kind==='faturasiz'?'Faturasız':'Faturalı',isRet(i)?'':i.cat].filter(Boolean).join(' · ');
const wType=c=>(db.withholdingTypes||[]).find(w=>w.code===c);
const frac=r=>r?Math.round(r*10)+'/10':'—';
const partnerName=id=>(db.partners||[]).find(p=>p.id===id)?.name;
const monthName=per=>new Date(per+'-15T12:00:00').toLocaleDateString('tr-TR',{month:'long',year:'numeric'});
const deadline=(per,day)=>{const [y,m]=per.split('-').map(Number);const d=new Date(y,m,day,12);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const pct=n=>'%'+new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(n||0);
const EXPENSE_CATS=['Malzeme','Taşeron / hakediş','İşçilik','Nakliye','Makine-ekipman kirası','Akaryakıt','Yemek','Ruhsat / harç','Proje / müşavirlik','Elektrik-su-doğalgaz','Kira','Sigorta','Vergi / SGK','Diğer gider'];
const INCOME_CATS=['Daire / konut satışı','İşyeri satışı','Hakediş','Kat karşılığı','Satış avansı / kaparo','Kira geliri','Diğer gelir'];
const scoped=x=>state.project==='all'||x.project===Number(state.project);
const bills=()=>db.invoices.filter(scoped).filter(i=>state.period==='all'||i.date.startsWith(state.period));
/* Ödemeler: inşaat kapsamı faturadan, dönem ödeme tarihinden. Karşılıksız/iade çekle yapılanlar varsayılan olarak hariç. */
const pays=(withVoid=false)=>{const ids=new Set(db.invoices.filter(scoped).map(i=>i.id));return db.payments.filter(p=>(withVoid||!p.void)&&ids.has(p.invoice)&&(state.period==='all'||p.date.startsWith(state.period)))};
const payFilter=p=>(p.id+' '+p.invoice+' '+p.method+' '+partyLabel(invOf(p))+' '+(partnerName(p.partner)||'')).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr'));
const cheques=()=>db.checks.filter(scoped);
const scopeName=()=>state.project==='all'?'Tüm İnşaatlar':db.projects.find(p=>p.id===Number(state.project))?.name||'Tüm İnşaatlar';
function filteredBills(){return bills().filter(i=>(i.id+' '+partyLabel(i)+' '+i.desc+' '+(i.cat||'')).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr'))&&(state.status==='Tümü'||(state.status==='Vadesi geçmiş'?remain(i)>0&&!isRet(i)&&i.due<today():state.status==='Vadesi yaklaşan'?remain(i)>0&&!isRet(i)&&i.due>=today()&&i.due<=addDays(today(),db.warning||7):state.status==='İade'?isRet(i):billStatus(i)===state.status))&&(state.kind==='all'||i.kind===state.kind)&&(state.dir==='all'||i.dir===state.dir))}
function field(label,name,type='text',value='',attrs=''){return `<label class="field"><span>${label}</span><input class="w-full rounded-lg border px-3 py-2.5 focus:outline-2 focus:outline-offset-2" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function options(arr,selected){return arr.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`}).join('')}
function selectField(label,name,arr,value,attrs=''){return `<label class="field"><span>${label}</span><select class="w-full rounded-lg border px-3 py-2.5" name="${name}" ${attrs}>${options(arr,value)}</select></label>`}
function button(label,action,ico='plus',primary=false,attrs=''){return `<button type="button" data-action="${action}" class="${primary?'primary ':''}inline-flex items-center justify-center gap-2 rounded-lg text-xs font-medium transition-colors" ${attrs}>${icon(ico,16)}${label}</button>`}
function badge(text,color='blue'){return `<span class="badge ${color}">${esc(text)}</span>`}
function cardHead(title,sub='',right=''){return `<div class="cardhead flex items-center justify-between gap-3"><div><h2 class="font-semibold">${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function totals(){const a=bills(),g=a.filter(i=>!isIncome(i)),r=a.filter(isIncome),ps=pays();return {invoice:sum(g,snet),income:sum(r,snet),payment:sum(ps.filter(p=>!flowIn(invOf(p))),p=>p.amount),collected:sum(ps.filter(p=>flowIn(invOf(p))),p=>p.amount),debt:sum(a.filter(i=>!flowIn(i)),remain),receivable:sum(a.filter(flowIn),remain),withheld:sum(g,wAmt),withheldIn:sum(r,wAmt),stopaj:sum(g,stopajAmt)}}
function invoiceTable(rows,printing=false){const cols=[['id','Belge / Açıklama'],['party','Cari / karşı taraf'],['date','Tarih'],['net','Net tutar'],['paid','Ödenen'],['remaining','Kalan'],['status','Durum']].filter(([k])=>printing||!state.hidden.includes(k));return `<div class="tablewrap overflow-x-auto"><table class="w-full text-left ${printing?'document-table':''}"><thead><tr>${cols.map(([k,label])=>`<th class="${['net','paid','remaining'].includes(k)?'num':''}">${label}</th>`).join('')}<th class="noprint"></th></tr></thead><tbody>${rows.map(i=>`<tr class="hover:bg-[#62766d]/5" data-detail="${esc(i.id)}">${cols.map(([k])=>{const val={id:`<b class="link">${esc(i.id)}</b><small><span class="dirtag ${isIncome(i)?'in':'out'}">${esc(tags(i))}</span>${i.rate?' · Tevkifat '+frac(i.rate)+(i.wcode?' ('+esc(i.wcode)+')':''):''}${i.stopaj?' · Stopaj '+pct(i.stopaj):''}</small>${i.desc?`<small class="clamp" title="${esc(i.desc)}">${esc(i.desc)}</small>`:''}`,party:`<b>${esc(partyLabel(i))}</b><small>${esc(projName(i.project))}</small>`,date:fmtDate(i.date),net:money(snet(i)),paid:money(paid(i)),remaining:`<b>${money(remain(i))}</b><span class="progress"><i style="width:${Math.min(100,(net(i)-remain(i))/net(i)*100)}%"></i></span>`,status:badge(statusLabel(i),remain(i)<.01?'green':paid(i)>0?'orange':'red')+(remain(i)>0&&!isRet(i)?((d=>d<0?`<small class="redtext">${-d} gün gecikti</small>`:d<=(db.warning||7)?`<small class="orangetext">${d?d+' gün kaldı':'Vadesi bugün'}</small>`:'')(daysTo(i.due))):'')};return `<td class="col-${k} ${['net','paid','remaining'].includes(k)?'num tabular-nums':''}">${val[k]}</td>`}).join('')}<td class="noprint">${icon('chevron',15)}</td></tr>`).join('')}</tbody><tfoot><tr>${cols.map(([k],j)=>`<td class="${['net','paid','remaining'].includes(k)?'num tabular-nums':''}">${j===0?'Toplam · '+rows.length+' kayıt':k==='net'?money(sum(rows,snet)):k==='paid'?money(sum(rows,paid)):k==='remaining'?money(sum(rows,remain)):''}</td>`).join('')}<td class="noprint"></td></tr></tfoot></table>${rows.length?'':'<div class="empty">Kayıt bulunamadı. Filtreleri değiştirin veya yeni kayıt ekleyin.</div>'}</div>`}
function metrics(){const t=totals(),c=cheques();return `<div class="stats grid grid-cols-2 xl:grid-cols-3 gap-4">${[['Toplam Gider',t.invoice,'blue','file','Faturalı + faturasız giderler · ödenen '+money(t.payment)],['Toplam Gelir',t.income,'green','wallet','Satış, hakediş ve diğer gelirler · tahsil '+money(t.collected)],['Kalan Borç',t.debt,'red','arrow','Ödenmeyi bekleyen giderler'],['KDV-2 Tevkifatı',t.withheld,'purple','percent','Alışlarda tevkif edilen KDV'],['Portföydeki Çek / Senet',sum(c.filter(x=>x.status==='Portföyde'),x=>x.amount),'orange','bank',c.length+' çek / senet kaydı'],['Kalan Alacak',t.receivable,'cyan','transfer','Tahsil edilmeyi bekleyen gelirler']].map(([l,v,color,ico,sub])=>`<div class="stat ${color} rounded-xl border"><div class="stathead flex items-center justify-between"><span>${l}</span><span class="iconbox">${icon(ico,19)}</span></div><strong class="tabular-nums">${money(v)}</strong><div class="statbottom"><span class="microdot"></span>${sub}</div></div>`).join('')}</div>`}
function chart(){const invoices=db.invoices.filter(i=>scoped(i)&&!isIncome(i)),payments=db.payments.filter(p=>!p.void&&invOf(p)&&scoped(invOf(p))&&!flowIn(invOf(p))),months=lastMonths(),t=totals(),max=Math.max(2000000,...months.map(m=>Math.max(sum(invoices.filter(i=>i.date.startsWith(m.prefix)),snet),sum(payments.filter(p=>p.date.startsWith(m.prefix)),p=>p.amount))));let method=['Havale / EFT','Çek','Nakit','Kredi Kartı','Senet'].map(m=>({name:m,amount:sum(payments.filter(p=>p.method===m),p=>p.amount)})).filter(x=>x.amount>0);const colors=['#314029','#62766d','#1b3c48','#96a889','#b8c6b2'];let accum=0,gradient=method.map((m,j)=>{const start=accum;accum+=t.payment?m.amount/t.payment*100:0;return `${colors[j]} ${start}% ${accum}%`}).join(',')||'#e2e7e0 0 100%';return `<div class="charts grid gap-5"><section class="card rounded-xl border">${cardHead('Finansal akış','Aylık gider ve ödeme dağılımı','<span class="chartkey"><i></i>Gider <i class="teal"></i>Ödeme</span>')}<div class="chart"><div class="ylabels">${[1,.75,.5,.25,0].map(n=>`<span>${(max*n/1000000).toLocaleString('tr-TR',{maximumFractionDigits:2})} mn ₺</span>`).join('')}</div><div class="plot">${months.map(({prefix,label:m},j)=>{let f=sum(invoices.filter(i=>i.date.startsWith(prefix)),snet),p=sum(payments.filter(p=>p.date.startsWith(prefix)),p=>p.amount);return `<div class="barcolumn ${j===5?'current':''}"><div class="bars"><div tabindex="0" title="${m} fatura: ${money(f)}" style="height:${Math.max(2,f/max*180)}px"></div><div tabindex="0" title="${m} ödeme: ${money(p)}" style="height:${Math.max(2,p/max*180)}px"></div></div><span>${m}</span></div>`}).join('')}</div></div><div class="chartfooter">${icon('chart',16)}<b>${money(t.payment)}</b><span>toplam ödeme gerçekleştirildi</span><span class="lightbadge">${today().slice(0,4)}</span></div></section><section class="card rounded-xl border">${cardHead('Ödeme yöntemleri','Ödemelerinizin dağılımı',icon('more'))}<div class="donut" style="background:conic-gradient(${gradient})"><div><small>Toplam ödeme</small><strong>${(t.payment/1000000).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} mn ₺</strong><span>${payments.length} işlem</span></div></div><div class="legend">${method.map((m,j)=>`<div><i style="background:${colors[j]}"></i><span>${m.name}</span><b>${Math.round(m.amount/t.payment*100)}%</b><small>${money(m.amount)}</small></div>`).join('')||'<div class="smallnote">Henüz ödeme kaydedilmedi.</div>'}</div></section></div>`}
function overview(){const dues=dueItems();return metrics()+chart()+`<div class="lowergrid grid gap-5"><section class="card">${cardHead('Yaklaşan ve geçmiş vadeler <span class="count">'+dues.length+'</span>','Faturalar ve çek / senetler · '+(db.warning||7)+' gün içinde dolacak veya gecikmiş',dues.length>5?'<button class="textbutton" data-action="reminders">Tümünü gör '+icon('arrow',14)+'</button>':'')}${dues.slice(0,5).map(dueRow).join('')||'<div class="empty">Yaklaşan veya geciken vade yok.</div>'}</section><section class="card">${cardHead('Son işlemler','Projenizdeki son finansal hareketler',pageLink('odemeler','<a class="textbutton" href="{url}">Tümü '+icon('arrow',14)+'</a>'))}${pays().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(p=>`<div class="activity"><span class="iconbox green">${icon('wallet',19)}</span><div><b>${flowIn(invOf(p))?'Tahsilat kaydedildi':'Ödeme kaydedildi'}${p.partner?' · '+esc(partnerName(p.partner)||''):''}</b><small>${esc(invOf(p)?.no||p.invoice)} · ${esc(p.method)}</small></div><div class="dueright"><b class="greentext">${money(p.amount)}</b><small>${fmtDate(p.date)}</small></div></div>`).join('')||'<div class="empty">Henüz ödeme yok.</div>'}</section></div><section class="card invoicecard">${cardHead('Son faturalar','Faturalarınız ve güncel ödeme durumları',pageLink('faturalar','<a class="textbutton" href="{url}">Tüm faturalar '+icon('arrow',15)+'</a>'))}${invoiceTable(bills().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4))}</section>`+(state.project==='all'?`<section class="card">${cardHead('İnşaat karşılaştırması')}<div class="tablewrap"><table><thead><tr><th>İnşaat</th><th class="num">Gelir (KDV hariç)</th><th class="num">Gider (KDV hariç)</th><th class="num">Net</th><th class="num">Kalan borç</th><th class="num">Kalan alacak</th></tr></thead><tbody>${db.projects.map(p=>{const a=bills().filter(i=>i.project===p.id),inc=a.filter(isIncome),exp=a.filter(i=>!isIncome(i)),n=sum(inc,sbase)-sum(exp,sbase);return `<tr><td>${esc(p.name)}</td><td class="num greentext">${money(sum(inc,sbase))}</td><td class="num">${money(sum(exp,sbase))}</td><td class="num ${n<0?'redtext':'greentext'}"><b>${money(n)}</b></td><td class="num">${money(sum(a.filter(i=>!flowIn(i)),remain))}</td><td class="num">${money(sum(a.filter(flowIn),remain))}</td></tr>`}).join('')}</tbody></table></div></section>`:'')}
function columnMenu(){return `<div id="columns" class="columns-menu hidden">${[['id','Fatura'],['party','Cari'],['date','Tarih'],['net','Net tutar'],['paid','Ödenen'],['remaining','Kalan'],['status','Durum']].map(([v,l])=>`<label class="checkboxline"><input type="checkbox" data-column="${v}" ${state.hidden.includes(v)?'':'checked'}>${l}</label>`).join('')}</div>`}
function invoicesPage(){return `<section class="card"><div class="toolbar"><div class="searchfield">${icon('search',17)}<input aria-label="Fatura ara" id="bill-search" placeholder="Belge no, cari, kategori veya açıklama ara" value="${esc(state.search)}"></div><select aria-label="Belge durumu" id="kind-filter">${options([['all','Faturalı + faturasız'],['faturali','Faturalı'],['faturasiz','Faturasız']],state.kind)}</select><select aria-label="Gelir / gider" id="dir-filter">${options([['all','Gelir + gider'],['gider','Giderler'],['gelir','Gelirler']],state.dir)}</select><select aria-label="Ödeme durumu" id="status-filter">${options(['Tümü','Ödendi','Kısmi ödendi','Ödenmedi','Vadesi geçmiş','Vadesi yaklaşan','İade'],state.status)}</select>${button('Sütunlar','columns','settings')}${button('Excel (CSV)','export','download')}</div>${columnMenu()}<div id="invoice-table">${invoiceTable(filteredBills())}</div></section>`}
function paymentsPage(){const all=pays(true).filter(payFilter),rows=all;return `<section class="card">${cardHead('Ödeme ve tahsilat hareketleri','Bağlı işlem, yöntem ve ödemeyi yapan / tahsil eden',`<b>${money(sum(rows.filter(p=>!p.void),p=>p.amount))}</b>`)}<div class="tablewrap"><table><thead><tr><th>İşlem no</th><th>Bağlı işlem</th><th>Cari / karşı taraf</th><th>Tarih</th><th>Yöntem</th><th>Ödeyen / tahsil eden</th><th class="num">Tutar</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.id)}</td><td><button class="textbutton" data-detail="${esc(p.invoice)}">${esc(p.invoice)}</button></td><td>${esc(partyLabel(invOf(p)))}</td><td>${fmtDate(p.date)}</td><td>${badge(p.method)} ${flowIn(invOf(p))?badge('Tahsilat','green'):badge('Ödeme','orange')}${p.void?' '+badge('Geçersiz · çek '+(db.checks.find(c=>c.id===p.checkId)?.status||'iptal'),'red'):''}${p.bankTx?`<small>${icon('bank',12)} ${esc(accLabel(accById((db.bankTx||[]).find(t=>t.id===p.bankTx)?.account))||'Banka hesabı')}</small>`:''}</td><td>${esc(partnerName(p.partner)||'Firma')}</td><td class="num ${flowIn(invOf(p))?'greentext':''}">${money(p.amount)}</td><td>${canEdit('odemeler')?`<button class="table-action" aria-label="Ödemeyi sil" data-action="delete-payment" data-id="${esc(p.id)}">${icon('trash',15)}</button>`:''}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6">Toplam · ${rows.filter(p=>!p.void).length} geçerli hareket</td><td class="num">${money(sum(rows.filter(p=>!p.void),p=>p.amount))}</td><td></td></tr></tfoot></table></div></section>`}
function withholdingPage(){const all=bills().filter(i=>i.kind!=='faturasiz'&&(i.rate>0||i.stopaj>0)),buy=all.filter(i=>!isIncome(i)),sell=all.filter(isIncome),tab=state.wtab,rows=tab==='alis'?buy:sell,ed=canEdit('tevkifat');
const cal=db.invoices.filter(i=>i.kind!=='faturasiz'&&!isIncome(i)&&(i.rate>0||i.stopaj>0)),months=[...new Set(cal.map(i=>i.date.slice(0,7)))].sort().reverse(),tp=(k,m)=>(db.taxPeriods||[]).find(t=>t.kind===k&&t.period===m);
const cell=(k,m,amount,day)=>{const t=tp(k,m),st=t?.status||'Bekliyor',dl=deadline(m,day),late=amount>0&&st!=='Ödendi'&&today()>dl;return amount>0?`<td class="num"><b>${money(amount)}</b></td><td class="${late?'redtext':''}">${fmtDate(dl)}${late?'<small>Süresi geçti</small>':''}</td><td><select aria-label="${k} ${m} durumu" data-taxperiod="${k}|${m}" ${ed?'':'disabled'}>${options(APP.meta.taxStatuses||['Bekliyor','Beyan edildi','Ödendi'],st)}</select>${t?.paid?`<small>Ödeme: ${fmtDate(t.paid)}</small>`:t?.declared?`<small>Beyan: ${fmtDate(t.declared)}</small>`:''}</td>`:'<td class="num muted">—</td><td></td><td></td>'};
return `<div class="wcards">${[['KDV-2 ile beyan edilecek',sum(buy,wAmt),'purple','Alışlarda sorumlu sıfatıyla tevkif ettiğimiz KDV'],['Satıcılara ödenecek KDV',sum(buy,i=>kdv(i)-wAmt(i)),'blue','Fatura KDV’si − tevkifat'],['Müşterinin tevkif ettiği KDV',sum(sell,wAmt),'green','Satışlarda · iade / mahsup konusu'],['Muhtasar stopajı',sum(buy,stopajAmt),'orange','Alışlarda kesip beyan edeceğimiz stopaj']].map(([l,v,c,sub])=>`<div class="card metric">${badge(l,c)}<strong>${money(v)}</strong><small>${sub}</small></div>`).join('')}</div>
<details class="card explain"><summary>${icon('percent',16)}<b>Tevkifat nasıl işler?</b><span>Alış, satış, KDV-2, KDV-1 ve stopaj</span></summary><div class="explaingrid"><div><h3>Alış (gider) faturasında</h3><p>Satıcıya <b>matrah + (KDV − tevkifat) − stopaj</b> ödenir. Tevkif edilen KDV, fatura tarihinin ait olduğu ay için <b>KDV-2</b> beyannamesiyle izleyen ayın <b>28'ine</b> kadar beyan edilip ödenir; aynı tutar KDV-1'de indirilecek KDV olarak dikkate alınır. Stopaj, <b>Muhtasar ve Prim Hizmet</b> beyannamesiyle izleyen ayın <b>26'sına</b> kadar beyan edilir.</p></div><div><h3>Satış (gelir) faturasında</h3><p>Alıcı, KDV'nin tevkifat kısmını kendisi beyan eder. KDV-1'de yalnızca <b>tahsil edilen KDV</b> (KDV − tevkifat) hesaplanan KDV olarak beyan edilir. Tevkifat nedeniyle indirilemeyen KDV <b>iade veya mahsup</b> yoluyla talep edilebilir. Müşterinin kestiği stopaj geçici vergi / kurumlar vergisinden mahsup edilir.</p></div><div><h3>Oranlar</h3><p>Tevkifat türü seçildiğinde oran otomatik gelir ve fatura bazında değiştirilebilir. Tür listesi ve varsayılan oranlar <b>Ayarlar → Tevkifat türleri</b> bölümünden güncellenir. KDV dahil tutar ${money(db.wLimit||0)} sınırının altındaysa form uyarır. Mevzuat değişebilir; oranları mali müşavirinizle teyit ediniz.</p></div></div></details>
<section class="card">${cardHead('Beyan takvimi','KDV-2 (sorumlu sıfatıyla KDV) ve Muhtasar (stopaj) · erişiminiz olan tüm inşaatların alış faturaları','')}<div class="tablewrap"><table><thead><tr><th>Dönem</th><th class="num">KDV-2 tutarı</th><th>Son gün</th><th>KDV-2 durumu</th><th class="num">Muhtasar stopajı</th><th>Son gün</th><th>Muhtasar durumu</th></tr></thead><tbody>${months.map(m=>{const r=cal.filter(i=>i.date.startsWith(m));return `<tr><td><b>${esc(monthName(m))}</b><small>${r.length} fatura</small></td>${cell('kdv2',m,sum(r,wAmt),28)}${cell('muhtasar',m,sum(r,stopajAmt),26)}</tr>`}).join('')||'<tr><td colspan="7"><div class="empty">Tevkifatlı veya stopajlı alış faturası yok.</div></td></tr>'}</tbody></table></div></section>
<section class="card">${cardHead('Tevkifatlı ve stopajlı faturalar','Seçili inşaat ve dönem',button('Excel (CSV)','export','download'))}<div class="toolbar">${[['alis','Alış faturaları ('+buy.length+')'],['satis','Satış faturaları ('+sell.length+')']].map(([k,l])=>`<button class="${tab===k?'primary':''}" data-action="wtab" data-tab="${k}">${l}</button>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Fatura</th><th>Cari</th><th>Tevkifat türü</th><th class="num">Matrah</th><th class="num">KDV</th><th>Oran</th><th class="num">Tevkif edilen KDV</th><th class="num">${tab==='alis'?'Satıcıya KDV':'Alıcıdan KDV'}</th><th class="num">Stopaj</th><th class="num">Net</th></tr></thead><tbody>${rows.map(i=>`<tr data-detail="${esc(i.id)}"><td><b>${esc(i.id)}</b><small>${fmtDate(i.date)}</small></td><td>${esc(partyLabel(i))}</td><td>${i.wcode?`<b>${esc(i.wcode)}</b><small>${esc(wType(i.wcode)?.name||'')}</small>`:'—'}</td><td class="num">${money(i.base)}</td><td class="num">${money(kdv(i))}</td><td>${i.rate?badge(frac(i.rate),'purple'):'—'}</td><td class="num"><b class="purpletext">${money(wAmt(i))}</b></td><td class="num">${money(kdv(i)-wAmt(i))}</td><td class="num">${i.stopaj?money(stopajAmt(i))+'<small>'+pct(i.stopaj)+'</small>':'—'}</td><td class="num"><b>${money(net(i))}</b></td></tr>`).join('')||'<tr><td colspan="10"><div class="empty">Kayıt yok.</div></td></tr>'}</tbody><tfoot><tr><td colspan="3">Toplam · ${rows.length} fatura</td><td class="num">${money(sum(rows,i=>i.base))}</td><td class="num">${money(sum(rows,kdv))}</td><td></td><td class="num">${money(sum(rows,wAmt))}</td><td class="num">${money(sum(rows,i=>kdv(i)-wAmt(i)))}</td><td class="num">${money(sum(rows,stopajAmt))}</td><td class="num">${money(sum(rows,net))}</td></tr></tfoot></table></div>${tab==='alis'?`<div class="totalbar"><span>KDV-1 indirilecek KDV <small>(satıcıya ödenen ${money(sum(buy,i=>kdv(i)-wAmt(i)))} + KDV-2 ile beyan ${money(sum(buy,wAmt))})</small></span><strong>${money(sum(buy,kdv))}</strong></div>`:`<div class="totalbar"><span>KDV-1 hesaplanan KDV <small>(tahsil edilen kısım) · tevkifattan doğan iade/mahsup hakkı ${money(sum(sell,wAmt))}</small></span><strong>${money(sum(sell,i=>kdv(i)-wAmt(i)))}</strong></div>`}</section>`}
const CHEQUE_FLOW=APP.meta?.chequeFlow||{alinan:['Portföyde','Tahsil edildi','Ciro edildi','İade edildi','Karşılıksız'],verilen:['Portföyde','Ödendi','İade edildi','Karşılıksız']};
const VOID_ST=['İade edildi','Karşılıksız'];
const chequeStatusLabel=(c,s)=>c.dir==='verilen'&&s==='Portföyde'?'Vadesi bekleniyor':s;
function checksPage(){const c=cheques(),ed=canEdit('cek-senet'),q=state.search.toLocaleLowerCase('tr'),tab=['Tümü','Alınan','Verilen'].includes(state.tab)?state.tab:'Tümü',rows=c.filter(x=>(tab==='Tümü'||(tab==='Alınan')===(x.dir!=='verilen'))&&(x.id+' '+party(x.party)+' '+x.bank).toLocaleLowerCase('tr').includes(q)),open=x=>x.status==='Portföyde';return `<div class="wcards">${[['Alınan · portföyde',sum(c.filter(x=>x.dir!=='verilen'&&open(x)),x=>x.amount),'green','Müşteriden alınan, henüz tahsil edilmemiş'],['Verilen · vadesi bekleyen',sum(c.filter(x=>x.dir==='verilen'&&open(x)),x=>x.amount),'orange','Kendi çek/senetlerimiz, henüz ödenmemiş'],['Vadesi geçmiş',sum(c.filter(x=>open(x)&&x.due<today()),x=>x.amount),'red','Durumu güncellenmemiş'],['Karşılıksız / iade',sum(c.filter(x=>VOID_ST.includes(x.status)),x=>x.amount),'purple','Bağlı ödemeler geçersiz sayılır']].map(([l,v,col,sub])=>`<div class="card metric">${badge(l,col)}<strong class="${col==='red'&&v?'redtext':''}">${money(v)}</strong><small>${sub}</small></div>`).join('')}</div><section class="card"><div class="toolbar">${['Tümü','Alınan','Verilen'].map(s=>`<button class="${tab===s?'primary':''}" data-action="check-tab" data-tab="${s}">${s}</button>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Belge no</th><th>Yön</th><th>Cari hesap</th><th>Banka / Tür</th><th>Vade</th><th>Kalan gün</th><th class="num">Tutar</th><th>Durum</th><th></th></tr></thead><tbody>${rows.map(c=>{const days=Math.ceil((Date.parse(c.due)-Date.parse(today()))/86400000),linked=db.payments.some(p=>p.checkId===c.id);return `<tr class="${days<0&&open(c)?'late':''}"><td><b>${esc(c.id)}</b>${linked?'<small>Ödemeye bağlı</small>':''}</td><td>${c.dir==='verilen'?badge('Verilen','orange'):badge('Alınan','green')}</td><td>${esc(party(c.party))}</td><td>${esc(c.bank)}<small>${esc(c.type)}</small></td><td>${fmtDate(c.due)}</td><td>${open(c)?badge(days<0?Math.abs(days)+' gün gecikti':days+' gün kaldı',days<0?'red':days<=(db.warning||7)?'orange':'blue'):'—'}</td><td class="num">${money(c.amount)}</td><td><select aria-label="Çek durumu" data-check-status="${esc(c.id)}" ${ed?'':'disabled'}>${options((CHEQUE_FLOW[c.dir]||CHEQUE_FLOW.alinan).map(s=>[s,chequeStatusLabel(c,s)]),c.status)}</select>${c.bankTx?`<small>${icon('bank',12)} Bankaya işlendi</small>`:''}</td><td class="nowrap">${ed?`<button class="table-action" aria-label="Düzenle" data-action="edit-check" data-id="${esc(c.id)}">${icon('edit',15)}</button><button class="table-action" aria-label="Sil" data-action="delete-check" data-id="${esc(c.id)}">${icon('trash',15)}</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="9" class="smallnote">Kayıt bulunamadı.</td></tr>'}</tbody></table></div><p class="reportnote">Alınan çek: müşteriden aldığımız (tahsil edilir / ciro edilir). Verilen çek: tedarikçiye verdiğimiz (vadesinde ödenir). “Karşılıksız” veya “İade edildi” yapılan çekle girilmiş ödeme geçersiz sayılır ve fatura yeniden açık görünür.</p></section>`}
/* Durum değişikliği: tahsil / ödeme anında banka hesabı seçilebilir */
async function changeChequeStatus(el){const c=db.checks.find(c=>c.id===el.dataset.checkStatus);if(!c)return;const s=el.value,linked=db.payments.some(p=>p.checkId===c.id);if(VOID_ST.includes(s)&&linked&&!await ask('Bu çek/senetle yapılan ödeme geçersiz sayılacak ve ilgili fatura yeniden açık görünecek. Devam edilsin mi?')){el.value=c.status;return}const accs=payAccounts(c.project);if(['Tahsil edildi','Ödendi'].includes(s)&&accs.length){showDialog(dialogFrame(s==='Ödendi'?'Çek ödendi':'Çek tahsil edildi',`<input type="hidden" name="pk" value="${c.pk}"><input type="hidden" name="status" value="${esc(s)}">${selectField('Banka hesabı',`bankAccount`,[['','— Bankaya işleme —'],...accs.map(a=>[a.id,accLabel(a)])],accs[0].id)}${field('Tarih','date','date',today(),'required')}<p class="smallnote">${money(c.amount)} tutarındaki ${esc(c.type.toLocaleLowerCase('tr'))}, seçilen hesaba ${s==='Ödendi'?'çıkış':'giriş'} olarak yazılır.</p>`,'chequestatus','',esc(c.type)+' '+esc(c.id)));el.value=c.status;return}act('PATCH','/api/checks/'+c.pk,{status:s})}
function partyBalance(p){const r=db.invoices.filter(i=>scoped(i)&&i.party===p.id),receivable=sum(r.filter(flowIn),remain),payable=sum(r.filter(i=>!flowIn(i)),remain);return {invoice:sum(r,snet),payment:sum(r,paid),receivable,payable,balance:Math.round((receivable-payable)*100)/100}}
const balanceText=b=>Math.abs(b)<.005?'Kapalı':b>0?'Alacak':'Borç';
function partiesPage(){const rows=db.parties.filter(p=>(!['120 Alıcılar','320 Satıcılar'].includes(state.page)||p.type===state.page)&&(p.name+' '+p.code).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr')));return `<section class="card">${cardHead('Cari hesap listesi','120 Alıcılar · 320 Satıcılar',button('Excel (CSV)','export','download'))}<div class="tablewrap"><table><thead><tr><th>Cari kodu</th><th>Ünvan</th><th>Hesap türü</th><th class="num">Fatura toplamı</th><th class="num">Net bakiye</th><th></th></tr></thead><tbody>${rows.map(p=>{let t=partyBalance(p);return `<tr data-party="${esc(p.id)}"><td class="link">${esc(p.code)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.type)}</td><td class="num">${money(t.invoice)}</td><td class="num ${t.balance>0?'greentext':t.balance<0?'redtext':''}">${money(Math.abs(t.balance))} ${balanceText(t.balance)}</td><td>${icon('chevron',15)}</td></tr>`}).join('')}</tbody></table></div></section>`}
/* Cari ekstre: firmamız açısından. Gelir faturası → cari borçlanır (Borç), tahsilat → Alacak.
   Gider faturası → cari alacaklanır (Alacak), ödeme → Borç. Bakiye = Borç − Alacak: (B) cari bize borçlu, (A) biz cariye borçluyuz. */
function ledgerRange(){if(state.start||state.end)return [state.start,state.end];if(state.period!=='all')return [state.period+'-01',state.period+'-31'];return ['','']}
function ledgerMoves(){const inv=db.invoices.filter(i=>scoped(i)&&(!state.cari||i.party===state.cari)),byId=new Map(inv.map(i=>[i.id,i])),out=[];for(const i of inv){const n=net(i);out.push({date:i.date,id:i.no||i.id,name:partyLabel(i),desc:tags(i)+(i.desc?' · '+i.desc:''),debit:flowIn(i)?n:0,credit:flowIn(i)?0:n})}for(const p of db.payments){const i=byId.get(p.invoice);if(!i||p.void)continue;out.push({date:p.date,id:p.id,name:partyLabel(i),desc:(flowIn(i)?'Tahsilat':'Ödeme')+' · '+p.method+' · '+(i.no||i.id),debit:flowIn(i)?0:p.amount,credit:flowIn(i)?p.amount:0})}return out.sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id)))}
function ledgerData(){const [s,e]=ledgerRange(),all=ledgerMoves(),before=all.filter(r=>s&&r.date<s),rows=all.filter(r=>(!s||r.date>=s)&&(!e||r.date<=e));const carry=Math.round(sum(before,r=>r.debit-r.credit)*100)/100;let run=carry;return {carry,start:s,rows:rows.map(r=>{run+=r.debit-r.credit;return {...r,bal:Math.round(run*100)/100}})}}
const balLabel=n=>Math.abs(n)<.005?money(0):money(Math.abs(n))+(n>0?' (B)':' (A)');
function ledgerRows(){return ledgerData().rows}
function ledgerTable(){const d=ledgerData(),rows=d.rows,end=rows.length?rows[rows.length-1].bal:d.carry;return `<div class="tablewrap"><table class="document-table"><thead><tr><th>Tarih</th><th>Belge / Açıklama</th>${state.cari?'':'<th>Cari</th>'}<th class="num">Borç</th><th class="num">Alacak</th><th class="num">Bakiye</th></tr></thead><tbody>${d.start?`<tr class="carryrow"><td>${fmtDate(d.start)}</td><td colspan="${state.cari?3:4}"><b>Devreden bakiye</b></td><td class="num"><b>${balLabel(d.carry)}</b></td></tr>`:''}${rows.map(r=>`<tr><td>${fmtDate(r.date)}</td><td><b>${esc(r.id)}</b><small class="clamp">${esc(r.desc)}</small></td>${state.cari?'':`<td>${esc(r.name)}</td>`}<td class="num">${r.debit?money(r.debit):''}</td><td class="num">${r.credit?money(r.credit):''}</td><td class="num"><b>${balLabel(r.bal)}</b></td></tr>`).join('')||`<tr><td colspan="${state.cari?5:6}" class="smallnote">Seçilen aralıkta hareket yok.</td></tr>`}</tbody><tfoot><tr><td colspan="${state.cari?2:3}">Dönem toplamı</td><td class="num">${money(sum(rows,r=>r.debit))}</td><td class="num">${money(sum(rows,r=>r.credit))}</td><td class="num">${balLabel(end)}</td></tr></tfoot></table></div><p class="reportnote">Borç: carinin bize borçlandığı tutar (satış faturası, yaptığımız ödeme). Alacak: carinin alacaklandığı tutar (alış faturası, aldığımız tahsilat). (B) cari bize borçlu · (A) biz cariye borçluyuz.</p>`}
