f.querySelector('[name=kind][value=faturali]').checked=true;if(v.direction)f.querySelector('[name=direction][value='+v.direction+']').checked=true;syncInvoiceForm();if(v.number)f.elements.id.value=v.number;if(v.date)f.elements.date.value=v.date;if(v.due)f.elements.due.value=v.due;if(v.base)f.elements.base.value=v.base;
