async function submitRecord(form){const data=new FormData(form),v=Object.fromEntries(data.entries()),kind=form.dataset.kind,btn=form.querySelector('[type=submit]');formError('');let method='POST',url,body;
if(kind==='invoice'){url='/api/invoices'+(form.dataset.edit?'/'+form.dataset.edit:'');body=data;if(!form.elements.document.files?.length)body.delete('document')}
else if(kind==='payment'){url='/api/payments';body={party:v.party,invoicePks:data.getAll('invoiceIds'),amount:v.amount,date:v.date,method:v.method,number:v.number||'',due:v.due||'',bank:v.bank||'',partner:v.partner||null,bankAccount:['Havale / EFT','Kredi Kartı'].includes(v.method)?(v.bankAccount||null):null}}
else if(kind==='return'){url='/api/invoices/'+v.of+'/return';body=data;if(!form.elements.document.files?.length)body.delete('document')}
else if(kind==='party'){url='/api/parties'+(v.pid?'/'+v.pid:'');method=v.pid?'PUT':'POST';body=v}
else if(kind==='bankaccount'){url='/api/bank-accounts'+(v.aid?'/'+v.aid:'');method=v.aid?'PUT':'POST';body={project:v.project,bank:v.bank,branch:v.branch,name:v.name,accountNo:v.accountNo,iban:v.iban,currency:v.currency,opening:v.opening,openingDate:v.openingDate,note:v.note,active:!!v.active}}
else if(kind==='banktx'){url='/api/bank-transactions'+(v.tid?'/'+v.tid:'');method=v.tid?'PUT':'POST';body={account:v.account,direction:v.direction,amount:v.amount,date:v.date,category:v.category,description:v.description,documentNo:v.documentNo};state.bank=Number(v.account)}
else if(kind==='transfer'){url='/api/bank-transfers';body=v}
else if(kind==='project'){url='/api/projects';body=v}
else if(kind==='check'){url='/api/checks'+(v.ck?'/'+v.ck:'');method=v.ck?'PUT':'POST';body=v}
else if(kind==='chequestatus'){url='/api/checks/'+v.pk;method='PATCH';body={status:v.status,bankAccount:v.bankAccount||null,date:v.date}}
else if(kind==='partner'){url='/api/partners'+(v.pid?'/'+v.pid:'');method=v.pid?'PUT':'POST';const shares={};for(const p of db.projects){const val=v['share_'+p.id];if(val!==''&&val!==undefined)shares[p.id]=val}body={name:v.name,phone:v.phone,note:v.note,shares}}
else if(kind==='password'){url='/api/password';body=v}
else if(kind==='user'){url='/api/users'+(v.uid?'/'+v.uid:'');method=v.uid?'PUT':'POST';body={name:v.name,email:v.email,password:v.password||'',role:v.role||null,super:!!v.super,active:!!v.active,allProjects:!!v.allProjects,projects:data.getAll('projects').map(Number)}}
else if(kind==='role'){url='/api/roles'+(v.rid?'/'+v.rid:'');method=v.rid?'PUT':'POST';const permissions={};for(const m of APP.meta.menu||[]){const l=v['perm_'+m.key];if(l&&l!=='none')permissions[m.key]=l}body={name:v.name,description:v.description,permissions}}
if(btn)btn.disabled=true;try{const r=await api(method,url,body);if(r.bankAccount){state.bank=r.bankAccount;state.stab='banka'}closeDialog();renderAll();notice(r.message)}catch(err){formError(err.message)}finally{if(btn)btn.disabled=false}}
/* Fatura detayı: üst bilgi, tutarlar, fatura aslı, kalemler, ödemeler, iadeler ve işlem geçmişi */
function docBlock(i){const ed=canEdit('faturalar'),url=`/api/invoices/${i.pk}/file`,ext=(i.file.split('.').pop()||'').toLowerCase();if(!i.hasFile)return `<div class="docempty">${icon('file',26)}<b>Fatura aslı yüklenmemiş</b><p>${i.file?'Kayıtta yalnızca dosya adı var: '+esc(i.file):'PDF, e-Fatura XML veya fotoğrafını yükleyin; buradan istediğiniz zaman açabilirsiniz.'}</p>${ed?`<label class="docupload">${icon('upload',16)} Belge yükle<input type="file" data-docupload="${i.pk}" accept=".pdf,.xml,.jpg,.jpeg,.png"></label>`:''}</div>`;
return `<div class="docbox"><div class="docmeta">${icon('file',20)}<span><b>${esc(i.file)}</b><small>${ext==='xml'?'e-Fatura XML · fatura görünümünde açılır':ext==='pdf'?'PDF belge':'Fotoğraf / tarama'}</small></span></div><div class="docactions"><a class="primarylink" href="${url}?inline=1" target="_blank" rel="noopener">${icon('arrow',15)} Aslını aç</a><a class="btnlink" href="${url}">${icon('download',15)} İndir</a>${ed?`<label class="btnlink docreplace">${icon('upload',15)} Değiştir<input type="file" data-docupload="${i.pk}" accept=".pdf,.xml,.jpg,.jpeg,.png"></label>`:''}</div>${ext==='pdf'?`<iframe class="docpreview" src="${url}?inline=1#toolbar=0&view=FitH" title="Fatura aslı önizleme"></iframe>`:['jpg','jpeg','png'].includes(ext)?`<img class="docpreview img" src="${url}?inline=1" alt="Fatura aslı">`:''}</div>`}
function detailInvoice(id){const i=db.invoices.find(i=>i.id===id);if(!i)return;const fat=i.kind!=='faturasiz',inn=flowIn(i),ret=isRet(i),orig=ret?db.invoices.find(x=>x.id===i.ret):null,rets=retsOf(i),ps=db.payments.filter(p=>p.invoice===id),st=billStatus(i),d=daysTo(i.due),rem=remain(i),A=Math.abs;
const amounts=[[fat?'Matrah':'Tutar',i.base],...(fat?[['KDV %'+i.vat,A(kdv(i))]]:[]),...(i.rate?[['KDV tevkifatı '+frac(i.rate)+(i.wcode?' · '+i.wcode:''),-A(wAmt(i))]]:[]),...(i.stopaj?[['Stopaj '+pct(i.stopaj),-A(stopajAmt(i))]]:[])];
const totalsRows=[[ret?'İade net tutarı':inn?'Tahsil edilecek net':'Ödenecek net',net(i),'strong'],...(rets.length?[['Kesilen iadeler',-credit(i)]]:[]),[ret?(inn?'Geri alınan':'Geri ödenen'):(inn?'Tahsil edilen':'Ödenen'),-paid(i)],[ret?(inn?'Geri alınacak':'Geri ödenecek'):'Kalan',rem,'strong']];
showDialog(`<div class="cardhead"><div><h2>${ret?'İade faturası':fat?'Fatura':'İşlem'} ${esc(i.no||i.id)}</h2><p>${esc(tags(i))} · ${esc(projName(i.project))}</p></div><button data-action="close" aria-label="Kapat">${icon('close',21)}</button></div>
<div class="invdetail"><div class="invtop"><div class="invparty"><small>${inn?'Müşteri / karşı taraf':'Tedarikçi / karşı taraf'}</small><b>${esc(partyLabel(i))}</b>${ret&&orig?`<small>İade edilen fatura: <button class="textbutton" data-detail="${esc(orig.id)}">${esc(orig.no||orig.id)}</button></small>`:''}</div><div><small>Tarih</small><b>${fmtDate(i.date)}</b></div><div><small>Vade</small><b>${fmtDate(i.due)}</b>${rem>0&&!ret?`<small class="${d<0?'redtext':d<=(db.warning||7)?'orangetext':''}">${d<0?A(d)+' gün gecikti':d===0?'Bugün':d+' gün kaldı'}</small>`:''}</div><div><small>Durum</small>${badge(statusLabel(i),rem<.01?'green':st==='Ödenmedi'?'red':'orange')}</div></div>
<div class="invcols"><section class="invbox"><h3>Tutarlar</h3>${amounts.map(([l,n])=>`<div class="invrow"><span>${esc(l)}</span><b>${money(n)}</b></div>`).join('')}<div class="invsep"></div>${totalsRows.map(([l,n,s])=>`<div class="invrow ${s||''}"><span>${esc(l)}</span><b>${money(n)}</b></div>`).join('')}${i.rate&&!inn&&!ret?`<p class="smallnote">KDV-2: ${monthName(i.date.slice(0,7))} · son gün ${fmtDate(deadline(i.date.slice(0,7),28))}</p>`:''}${i.stopaj&&!inn&&!ret?`<p class="smallnote">Muhtasar: ${monthName(i.date.slice(0,7))} · son gün ${fmtDate(deadline(i.date.slice(0,7),26))}</p>`:''}</section>
<section class="invbox"><h3>Fatura aslı</h3>${docBlock(i)}${i.ettn?`<p class="smallnote mono">ETTN: ${esc(i.ettn)}</p>`:''}</section></div>
${i.desc?`<section class="invbox"><h3>Açıklama</h3><p>${esc(i.desc)}</p></section>`:''}
${i.items?.length?`<section class="invbox"><h3>Fatura kalemleri</h3><div class="tablewrap"><table><thead><tr><th>Mal / hizmet</th><th class="num">Miktar</th><th class="num">Birim fiyat</th><th class="num">KDV</th><th class="num">Tutar</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${esc(x.name)}${x.code?`<small>${esc(x.code)}</small>`:''}</td><td class="num">${qty(x.qty)} ${esc(x.unit||'')}</td><td class="num">${x.price!=null?money(x.price):''}</td><td class="num">${x.vatRate!=null?'%'+qty(x.vatRate):''}</td><td class="num">${x.total!=null?money(x.total):''}</td></tr>`).join('')}</tbody></table></div></section>`:''}
<section class="invbox"><h3>${inn?'Tahsilatlar':'Ödemeler'}</h3>${ps.map(p=>`<div class="invrow"><span>${fmtDate(p.date)} · ${esc(p.method)}${p.checkId?' '+esc(p.checkId):''} · ${esc(partnerName(p.partner)||'Firma')}${p.void?' '+badge('Geçersiz','red'):''}</span><b>${money(p.amount)}</b></div>`).join('')||`<p class="smallnote">Henüz ${inn?'tahsilat':'ödeme'} yok.</p>`}</section>
${rets.length?`<section class="invbox"><h3>İade faturaları</h3>${rets.map(r=>`<div class="invrow tableclick" data-detail="${esc(r.id)}"><span>${fmtDate(r.date)} · ${esc(r.no||r.id)}</span><b>− ${money(net(r))}</b></div>`).join('')}</section>`:''}
<details class="invbox history" data-history="${i.pk}"><summary><h3>İşlem geçmişi</h3><span class="smallnote">Kim, ne zaman ekledi / değiştirdi</span></summary><div class="historybody smallnote">Yükleniyor…</div></details></div>
<div class="modalfooter">${canEdit('faturalar')?button('Sil','delete-invoice','trash',false,`data-id="${esc(i.id)}"`)+(ret?'':button('Düzenle','edit-invoice','edit',false,`data-id="${esc(i.id)}"`))+(!ret&&returnableBase(i)>0?button('İade faturası','add-return-inv','transfer',false,`data-id="${esc(i.id)}"`):''):'<span></span>'}${canEdit('odemeler')&&rem>0?button(inn?(ret?'İade tahsil et':'Tahsilat Ekle'):(ret?'İadeyi öde':'Ödeme Ekle'),'pay-invoice','wallet',true,`data-id="${esc(i.id)}"`):''}</div>`);document.getElementById('record-dialog').classList.add('wide')}
async function loadHistory(el){if(el.dataset.loaded)return;el.dataset.loaded=1;const box=el.querySelector('.historybody');try{const r=await fetch('/api/logs?type=invoice&id='+el.dataset.history,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);box.innerHTML=d.logs.map(logLine).join('')||'Kayıt yok. (İşlem geçmişi bu özellik eklendikten sonraki değişiklikleri tutar.)'}catch(e){box.textContent=e.message||'Geçmiş yüklenemedi.'}}
/* İade faturası formu */
function returnDialog(i){const max=returnableBase(i);showDialog(dialogFrame((isIncome(i)?'Satış':'Alış')+' iade faturası',`<input type="hidden" name="of" value="${i.pk}"><div class="warning">${icon('transfer')}${esc(i.no||i.id)} · ${esc(partyLabel(i))} faturasının iadesi. KDV %${i.vat}${i.rate?', tevkifat '+frac(i.rate):''}${i.stopaj?', stopaj '+pct(i.stopaj):''} oranları asıl faturadan alınır.</div><div class="formgrid">${field('İade fatura no','number','text','','required maxlength="100"')}${field('İade tarihi','date','date',today(),'required min="'+i.date+'"')}</div>${field('İade matrahı (KDV hariç, ₺) · en fazla '+money(max),'base','number',max,'required min="0.01" step="0.01" max="'+max+'" id="return-base"')}${field('Açıklama','desc','text','','placeholder="Örn. hatalı / eksik teslim edilen malzeme"')}<label class="field"><span>İade faturası aslı (isteğe bağlı)</span><input type="file" name="document" accept=".pdf,.xml,.jpg,.jpeg,.png"></label><div id="return-calc" class="calculations"></div><p class="smallnote">${isIncome(i)?'Satış iadesi müşterinin borcunu azaltır; fatura tahsil edilmişse fazlası müşteriye geri ödenecek tutar olarak izlenir.':'Alış iadesi tedarikçiye olan borcu azaltır; fatura ödenmişse fazlası tedarikçiden geri alınacak tutar olarak izlenir.'} KDV ve tevkifat düzeltmesini mali müşavirinizle teyit edin.</p>`,'return','',esc(projName(i.project))));calcReturn()}
function calcReturn(){const f=document.getElementById('record-form'),box=document.getElementById('return-calc');if(!f||!box||f.dataset.kind!=='return')return;const i=db.invoices.find(x=>x.pk===Number(f.elements.of.value)),b=Number(f.elements.base.value)||0,x={...i,base:b,ret:i.id};box.innerHTML=`<span>Matrah <b>${money(b)}</b></span><span>KDV <b>${money(A_(kdv(x)))}</b></span>${i.rate?`<span>Tevkifat <b>− ${money(A_(wAmt(x)))}</b></span>`:''}${i.stopaj?`<span>Stopaj <b>− ${money(A_(stopajAmt(x)))}</b></span>`:''}<strong>İade net <b>${money(net(x))}</b></strong>`}
const A_=Math.abs;
function detailParty(id,tab='Hareketler'){const p=db.parties.find(p=>p.id===id);if(!p)return;state.detailTab=tab;const t=partyBalance(p),rows=db.invoices.filter(i=>scoped(i)&&i.party===id);let body='';if(tab==='Faturalar'){const h=state.hidden;state.hidden=[...h,'party'];body=invoiceTable(rows);state.hidden=h}else if(tab==='Ödemeler')body=`<div class="tablewrap"><table><thead><tr><th>İşlem</th><th>Tarih</th><th class="num">Tutar</th></tr></thead><tbody>${db.payments.filter(x=>rows.some(i=>i.id===x.invoice)).map(x=>`<tr><td>${esc(x.invoice)}</td><td>${fmtDate(x.date)}</td><td class="num">${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`;else if(tab==='Çek/Senet')body=`<div class="tablewrap"><table><thead><tr><th>Belge</th><th>Vade</th><th class="num">Tutar</th></tr></thead><tbody>${cheques().filter(c=>c.party===id).map(c=>`<tr><td>${esc(c.id)}</td><td>${fmtDate(c.due)}</td><td class="num">${money(c.amount)}</td></tr>`).join('')}</tbody></table></div>`;else{const prior=state.cari;state.cari=id;body=ledgerTable();state.cari=prior}showDialog(`<div class="cardhead"><div><h2>${esc(p.name)}</h2><p>${esc(p.code)} · ${esc(p.type)}</p></div><button data-action="close" aria-label="Kapat">${icon('close',21)}</button></div><div class="modalbody"><span class="badge ${t.balance>0?'green':t.balance<0?'red':'blue'}">${t.balance>0?'Net alacağımız':t.balance<0?'Net borcumuz':'Bakiye kapalı'}</span><h1 class="my-4">${money(Math.abs(t.balance))}</h1><div class="partysum"><div><small>Kalan alacağımız (satış)</small><b class="greentext">${money(t.receivable)}</b></div><div><small>Kalan borcumuz (alış)</small><b class="redtext">${money(t.payable)}</b></div><div><small>Ödenen / tahsil edilen</small><b>${money(t.payment)}</b></div></div><div class="tabs mt-5">${['Hareketler','Faturalar','Ödemeler','Çek/Senet'].map(s=>`<button class="${tab===s?'selected':''}" data-action="party-tab" data-id="${esc(id)}" data-tab="${s}">${s}</button>`).join('')}</div></div>${body}<div class="modalfooter">${button('Kapat','close','close')}${canEditParties()?button('Cariyi düzenle','edit-party','edit',false,`data-id="${esc(id)}"`):''}${pageLink('hesap-ekstresi',`<a class="btnlink" href="{url}?cari=${encodeURIComponent(id)}">Hesap ekstresine git ${icon('arrow',16)}</a>`)}</div>`);document.getElementById('record-dialog').classList.add('wide')}
function init(){state.page=document.body.dataset.page||'Genel Bakış';state.project=String(db.projects[0]?.id??'all');try{const c=JSON.parse(localStorage.getItem('gundogdu-context-'+ME.id)||'{}');if(c.project)state.project=String(c.project);if(c.period)state.period=c.period;const hidden=JSON.parse(localStorage.getItem('gundogdu-columns-'+ME.id)||'[]');if(Array.isArray(hidden))state.hidden=hidden}catch{}if(state.project!=='all'&&!db.projects.some(p=>p.id===Number(state.project)))state.project='all';document.getElementById('app-root').innerHTML=shell();const qs=new URLSearchParams(location.search);state.search=qs.get('q')||'';state.cari=qs.get('cari')||'';if(state.cari&&!db.parties.some(p=>p.id===state.cari))state.cari='';if(state.cari&&state.page==='Hesap Ekstresi'){state.stab='cari';document.getElementById('app-root').innerHTML=shell()}if(!periodOptions().some(([v])=>v===state.period))state.period='all';renderAll();try{document.getElementById('application').classList.toggle('dark',localStorage.getItem('gundogdu-theme')==='dark')}catch{}if(APP.notice)notice(APP.notice);
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(btn){const a=btn.dataset.action,id=btn.dataset.id;if(a==='close')return requestClose();if(a==='logout')return document.getElementById('logout-form').submit();if(a==='delete-user'){const u=(db.users||[]).find(u=>u.id===Number(id));if(u&&await ask(u.name+' kullanıcısı silinsin mi? Bu işlem geri alınamaz.'))act('DELETE','/api/users/'+u.id);return}if(a==='delete-role'){const r=(db.roles||[]).find(r=>r.id===Number(id));if(r&&await ask(r.name+' rolü silinsin mi?'))act('DELETE','/api/roles/'+r.id);return}if(a==='theme'){const dark=document.getElementById('application').classList.toggle('dark');try{localStorage.setItem('gundogdu-theme',dark?'dark':'light')}catch{}return}if(a==='mobile-menu')return document.getElementById('sidebar').classList.toggle('mobileopen');if(a==='collapse')return document.getElementById('application').classList.toggle('collapsed');if(a==='columns')return document.getElementById('columns')?.classList.toggle('hidden');if(a==='export')return exportData();if(a==='backup')return backup();if(a==='print')return window.print();if(a.startsWith('add-')&&a!=='add-return-inv')return newRecord(a.slice(4));if(a==='invoice-next'){invoiceStepTwo();toggleNewParty();document.querySelector('#record-form [name=id]').focus();return}if(a==='wtab'){state.wtab=btn.dataset.tab;renderContent();return}if(a==='bank-project'){state.project=id;state.bank=0;saveContext();renderAll();return}if(a==='theme-preset'){const f=document.getElementById('theme-form');for(const [k,v] of [['menu',btn.dataset.m],['accent',btn.dataset.a],['bg',btn.dataset.b]]){f.elements[k].value=v;f.querySelector(`[data-theme-hex=${k}]`).value=v}saveTheme({menu:btn.dataset.m,accent:btn.dataset.a,bg:btn.dataset.b,font:f.elements.font.value,scale:f.elements.scale.value,layout:f.elements.layout.value});return}if(a==='theme-reset'){if(await ask('Tema varsayılan görünüme döndürülsün mü? Logo, renkler, yazı tipi ve boyutu sıfırlanır.',{danger:false,ok:'Evet, sıfırla'}))saveTheme({reset:1});return}if(a==='theme-logo-remove'){if(await ask('Sistem logosu kaldırılsın mı?',{danger:false,ok:'Evet, kaldır'})){const fd=new FormData();fd.append('removeLogo','1');saveTheme(fd,'Sistem logosu kaldırıldı.')}return}if(a==='settab'){state.settab=btn.dataset.tab;renderContent();return}if(a==='stab'){state.stab=btn.dataset.tab;rebuildShell();return}if(a==='banktx-in'||a==='banktx-out')return newRecord('banktx',{dir:a==='banktx-in'?'giris':'cikis',account:state.bank});if(a==='edit-bankaccount'){const x=accById(id);if(x)newRecord('bankaccount',x);return}if(a==='delete-bankaccount'){const x=accById(id);if(!x)return;if(accTx(x.id).length)return notice('Hareketi olan banka hesabı silinemez. Kullanmayacaksanız “Aktif” işaretini kaldırın.');if(await ask(accLabel(x)+' hesabı silinsin mi?')){closeDialog();act('DELETE','/api/bank-accounts/'+x.id)}return}if(a==='edit-banktx'){const t=(db.bankTx||[]).find(t=>t.id===Number(id));if(t)newRecord('banktx',t);return}if(a==='delete-banktx'){const t=(db.bankTx||[]).find(t=>t.id===Number(id));if(t&&await ask(t.transfer?'Virman silinecek; iki hesaptaki hareket birlikte kalkar. Devam edilsin mi?':'Banka hareketi silinsin mi?'))act('DELETE','/api/bank-transactions/'+t.id);return}if(a==='delete-partner'){const x=(db.partners||[]).find(x=>x.id===Number(id));if(x&&await ask(x.name+' ortağı silinsin mi?'))act('DELETE','/api/partners/'+x.id);return}if(a==='delete-wtype'){if(await ask(id+' tevkifat türü silinsin mi?'))act('DELETE','/api/withholding-types/'+id);return}if(a==='add-return-inv'){const x=db.invoices.find(x=>x.id===id);if(x)returnDialog(x);return}if(a==='reminders')return showReminders();if(a==='logs-more')return loadLogs(true);if(a==='edit-invoice'){const x=db.invoices.find(x=>x.id===id);if(x){closeDialog();newRecord('invoice',{edit:x})}return}if(a==='edit-party'){const x=db.parties.find(x=>x.id===id);if(x){closeDialog();newRecord('party',x)}return}if(a==='delete-party'){const x=db.parties.find(x=>x.id===id);if(x&&await ask(x.name+' cari hesabı silinsin mi?')){closeDialog();act('DELETE','/api/parties/'+x.id)}return}if(a==='edit-check'){const x=db.checks.find(x=>x.id===id);if(x)newRecord('check',x);return}if(a==='delete-check'){const x=db.checks.find(x=>x.id===id);if(!x)return;const linked=db.payments.some(p=>p.checkId===x.id);if(await ask(x.id+' silinsin mi?'+(linked?' Bu çekle yapılan ödemeler de silinecek ve faturalar yeniden açık görünecek.':'')+(x.bankTx?' Bankaya işlenen hareket de silinecek.':'')))act('DELETE','/api/checks/'+x.pk);return}if(a==='rename-project'){const pr=db.projects.find(p=>p.id===Number(id));const n=pr&&await askText('İnşaat adını değiştir',pr.name,{text:'Yeni inşaat adını yazın.'});if(n&&n.trim()&&n.trim()!==pr.name)act('PUT','/api/projects/'+pr.id,{name:n.trim()});return}if(a==='check-tab'){state.tab=btn.dataset.tab;renderContent();return}if(a==='report'){state.report=Number(btn.dataset.report);renderContent();return}if(a==='party-tab'){document.getElementById('record-dialog').close();detailParty(id,btn.dataset.tab);return}if(a==='pay-invoice'){const i=db.invoices.find(i=>i.id===id);if(!i)return;closeDialog();newRecord('payment',{party:i.party,invoice:i.id,amount:remain(i),income:flowIn(i)});return}if(a==='delete-invoice'){if(db.payments.some(p=>p.invoice===id))return notice('Bağlı ödeme bulunan fatura silinemez. Önce ilgili ödemeleri kaldırınız.');if(db.invoices.some(x=>x.ret===id))return notice('Bu faturaya kesilmiş iade faturası var; önce iade faturasını silin.');const inv=db.invoices.find(i=>i.id===id);if(inv&&await ask(id+' faturası silinsin mi?')){closeDialog();act('DELETE','/api/invoices/'+inv.pk)}return}if(a==='delete-payment'){const p=db.payments.find(p=>p.id===id);if(p?.checkId&&db.checks.some(c=>c.id===p.checkId))return notice('Ödeme bir çek/senede bağlıdır. Bu kayıt doğrudan silinemez.');if(p&&await ask('Ödeme silinecek ve fatura kalanı yeniden hesaplanacak.'+(p.bankTx?' Bağlı banka hareketi de düzeltilecek.':'')+' Devam edilsin mi?'))act('DELETE','/api/payments/'+p.pk);return}if(a==='delete-project'){const n=Number(id);if(db.invoices.some(i=>i.project===n)||db.checks.some(c=>c.project===n)||(db.bankAccounts||[]).some(a=>a.project===n))return notice('Bağlı kayıtları (fatura, çek, banka hesabı) olan inşaat silinemez.');if(await ask('İnşaat silinsin mi?')){act('DELETE','/api/projects/'+n).then(r=>{if(r&&state.project===String(n)){state.project='all';renderAll()}})}return}}const detail=e.target.closest('[data-detail]');if(detail){detailInvoice(detail.dataset.detail);return}const p=e.target.closest('[data-party]');if(p)return detailParty(p.dataset.party);const bk=e.target.closest('[data-bank]');if(bk){state.bank=Number(bk.dataset.bank);renderContent();return}const pt=e.target.closest('[data-partner]');if(pt){const x=(db.partners||[]).find(x=>x.id===Number(pt.dataset.partner));if(x)newRecord('partner',x);return}const u=e.target.closest('[data-user]');if(u){const x=(db.users||[]).find(x=>x.id===Number(u.dataset.user));if(x)newRecord('user',x);return}const r=e.target.closest('[data-role]');if(r){const x=(db.roles||[]).find(x=>x.id===Number(r.dataset.role));if(x)newRecord('role',x)}});
document.addEventListener('submit',e=>{if(e.target.id==='theme-form'){e.preventDefault();const f=e.target;saveTheme({menu:f.elements.menu.value,accent:f.elements.accent.value,bg:f.elements.bg.value,font:f.elements.font.value,scale:f.elements.scale.value,layout:f.elements.layout.value});return}if(e.target.getAttribute('id')==='record-form'){e.preventDefault();submitRecord(e.target)}if(e.target.id==='company-form'){e.preventDefault();const d=new FormData(e.target);act('POST','/api/settings/company',{company:d.get('company'),tax:d.get('tax'),address:d.get('address')})}if(e.target.id==='wtype-form'){e.preventDefault();const d=new FormData(e.target);act('POST','/api/withholding-types',{code:d.get('code'),name:d.get('name'),rate:d.get('rate'),active:true})}if(e.target.id==='global-search-form'){e.preventDefault();location.href='/faturalar?q='+encodeURIComponent(new FormData(e.target).get('q')||'')}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.themeColor){const h=el.form.querySelector(`[data-theme-hex=${el.dataset.themeColor}]`);if(h)h.value=el.value}if(el.dataset.themeHex&&/^#[0-9a-f]{6}$/i.test(el.value)){el.form.elements[el.dataset.themeHex].value=el.value.toLowerCase()}if(el.closest?.('#record-dialog form'))document.getElementById('record-dialog').dataset.dirty='1';if(el.id==='return-base')calcReturn();if(el.matches('[data-calc]'))calcInvoice();if(el.id==='payment-amount')paymentWarning();if(el.id==='bill-search'){state.search=el.value;document.getElementById('invoice-table').innerHTML=invoiceTable(filteredBills())}});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='layout'&&el.form?.id==='theme-form'){el.form.querySelectorAll('.layoutopt').forEach(o=>o.classList.toggle('selected',o.contains(el)&&el.checked));const f=el.form;saveTheme({menu:f.elements.menu.value,accent:f.elements.accent.value,bg:f.elements.bg.value,font:f.elements.font.value,scale:f.elements.scale.value,layout:el.value},el.value==='top'?'Menü üste alındı.':'Menü sola alındı.');return}if(el.id==='theme-logo'){const f=el.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>300000){notice('Sistem logosu 300 KB altında PNG, JPG veya WEBP olmalıdır.','error');el.value='';return}const fd=new FormData();fd.append('logo',f);saveTheme(fd,'Sistem logosu kaydedildi.');return}if(el.id==='theme-font-select'){const pv=document.getElementById('font-preview');if(pv){const fam=el.value;pv.style.fontFamily=fam==='Sistem yazı tipi'?'-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Arial,sans-serif':`'${fam}',Arial,sans-serif`;if(fam!=='Sistem yazı tipi'&&fam!=='Inter'&&!document.getElementById('pv-font-'+fam.replace(/\W/g,''))){const l=document.createElement('link');l.id='pv-font-'+fam.replace(/\W/g,'');l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+fam.replace(/ /g,'+')+':wght@400;600&display=swap';document.head.appendChild(l)}}}if(el.closest?.('#record-dialog form')&&!el.dataset.docupload)document.getElementById('record-dialog').dataset.dirty='1';if(el.dataset.docupload){const f=el.files?.[0];if(!f)return;const fd=new FormData();fd.append('document',f);const inv=db.invoices.find(x=>x.pk===Number(el.dataset.docupload));try{const r=await api('POST','/api/invoices/'+el.dataset.docupload+'/document',fd);notice(r.message);renderAll();if(inv)detailInvoice(inv.id)}catch(err){notice(err.message)}return}if(el.dataset.logf){state.log[el.dataset.logf]=el.value;state.log.loaded=false;loadLogs();return}if(el.id==='project-select'){if(el.value==='new'){el.value=state.project;return newRecord('project')}state.project=el.value;saveContext();renderAll()}if(el.id==='period-select'){state.period=el.value;saveContext();renderAll()}if(el.id==='status-filter'){state.status=el.value;renderContent()}if(el.id==='kind-filter'){state.kind=el.value;renderContent()}if(el.id==='dir-filter'){state.dir=el.value;renderContent()}if(el.form?.dataset.kind==='invoice'&&['kind','direction','project','payNow','payMethod'].includes(el.name))syncInvoiceForm();if(el.id==='wcode'){const w=wType(el.value);el.form.elements.rate.value=w?String(w.rate):'0';calcInvoice()}if(el.dataset.taxperiod){const [k,m]=el.dataset.taxperiod.split('|');act('POST','/api/tax-periods',{kind:k,period:m,status:el.value})}if(el.dataset.wtype){const w=wType(el.dataset.wtype);if(w)act('POST','/api/withholding-types',{code:w.code,name:w.name,rate:el.dataset.field==='rate'?el.value:w.rate,active:el.dataset.field==='active'?el.checked:w.active})}if(el.id==='wlimit'){act('POST','/api/settings/tax',{wLimit:el.value})}if(el.dataset.column){state.hidden=el.checked?state.hidden.filter(c=>c!==el.dataset.column):[...state.hidden,el.dataset.column];saveContext();document.getElementById('invoice-table').innerHTML=invoiceTable(filteredBills())}if(el.matches('[data-calc]'))calcInvoice();if(el.id==='payment-party')renderOpenInvoices();if(el.name==='document'&&el.form?.dataset.kind==='invoice')readInvoice(el);if(el.name==='party'&&el.form?.dataset.kind==='invoice')toggleNewParty();if(el.name==='invoiceIds')paymentWarning();if(el.id==='payment-method'){document.getElementById('payment-extra').classList.toggle('hidden',!['Çek','Senet'].includes(el.value));document.getElementById('payment-bank')?.classList.toggle('hidden',!['Havale / EFT','Kredi Kartı'].includes(el.value))}if(el.dataset.checkStatus)changeChequeStatus(el);if(['bank-start','bank-end','bank-dir'].includes(el.id)){state[{'bank-start':'bstart','bank-end':'bend','bank-dir':'bdir'}[el.id]]=el.value;renderContent()}if(el.form?.dataset.kind==='banktx'&&el.name==='direction'){document.getElementById('banktx-cats').innerHTML=(el.value==='giris'?BANK_IN:BANK_OUT).map(c=>`<option value="${esc(c)}">`).join('')}if(['ledger-party','ledger-start','ledger-end'].includes(el.id)){const key={'ledger-party':'cari','ledger-start':'start','ledger-end':'end'}[el.id];state[key]=el.value;renderContent()}if(el.id==='warning-days'){const n=Number(el.value);if(n<1||n>90){notice('1–90 arasında gün giriniz.');return}act('POST','/api/settings/warning',{warning:n})}if(el.id==='logo-file'){const f=el.files?.[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>500000)return notice('500 KB altında PNG veya JPG seçiniz.');const fd=new FormData();fd.append('logo',f);act('POST','/api/settings/logo',fd)}if(el.id==='restore-file'){const f=el.files?.[0];if(!f)return;if(!await ask('Veritabanındaki tüm muhasebe kayıtları bu yedek ile değiştirilsin mi? Bu işlem geri alınamaz.')){el.value='';return}const fd=new FormData();fd.append('backup',f);const r=await act('POST','/api/restore',fd);if(r){state.project='all';renderAll()}}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('details[data-history]')&&e.target.open)loadHistory(e.target)},true);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}});document.addEventListener('cancel',e=>{if(e.target.id==='record-dialog'){e.preventDefault();requestClose()}},true);let backdropDown=false;document.addEventListener('mousedown',e=>{backdropDown=e.target.id==='record-dialog'&&(()=>{const r=e.target.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom})()});document.addEventListener('click',e=>{if(e.target.id==='record-dialog'&&backdropDown){backdropDown=false;requestClose()}});}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',init);
